// keep in sync with n8n/workflows/lead-inbound.mjs
const INBOUND_LEAD_ALLOWLIST = ['contact_name','work_email','company_name','product_family_code','fcl_band','content_topic'];
const PRODUCT_FAMILY_CODES = ['ONION','GARLIC','CHILLI','OTHER'];
const FCL_BANDS = ['1','2_5','6_plus'];
const CONTENT_TOPICS = ['sfcr','coa_spec','steam_sterilization'];
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
function assertInboundLead(payload) {
  if (payload == null || typeof payload !== 'object' || Array.isArray(payload)) throw new Error('payload required');
  for (const key of Object.keys(payload)) {
    if (!INBOUND_LEAD_ALLOWLIST.includes(key)) throw new Error('unknown inbound lead key forbidden: ' + key);
    if (payload[key] != null && typeof payload[key] === 'object') throw new Error('nested objects forbidden');
  }
  for (const key of INBOUND_LEAD_ALLOWLIST) {
    if (!(key in payload)) throw new Error('missing ' + key);
    if (typeof payload[key] !== 'string' || !payload[key].trim()) throw new Error(key + ' must be a non-empty string');
  }
  const email = payload.work_email.trim().toLowerCase();
  if (!EMAIL_RE.test(email) || email.length > 120) throw new Error('work_email must be a short email');
  if (!PRODUCT_FAMILY_CODES.includes(payload.product_family_code)) throw new Error('unknown product_family_code');
  if (!FCL_BANDS.includes(payload.fcl_band)) throw new Error('unknown fcl_band');
  if (!CONTENT_TOPICS.includes(payload.content_topic)) throw new Error('unknown content_topic');
}
const input = $input.first().json;
const headers = input.headers ?? {};
const provided = headers['x-sattva-webhook-hmac'] ?? headers['X-Sattva-Webhook-Hmac'];
const expected = $env.N8N_LEAD_INBOUND_HMAC;
if (typeof expected !== 'string' || !expected || typeof provided !== 'string' || provided !== expected) {
  throw new Error('invalid x-sattva-webhook-hmac');
}
const payload = input.body ?? input;
assertInboundLead(payload);
const work_email = payload.work_email.trim().toLowerCase();
const hashed_partner_id = require('crypto').createHash('sha256').update(work_email).digest('hex');
return [{ json: {
  contact_name: payload.contact_name.trim().slice(0, 120),
  work_email,
  company_name: payload.company_name.trim().slice(0, 120),
  product_family_code: payload.product_family_code,
  fcl_band: payload.fcl_band,
  content_topic: payload.content_topic,
  hashed_partner_id,
} }];

// keep in sync with n8n/workflows/leadscore.mjs; do not pass work_email
const inbound = $('Allowlist inbound lead').first().json;
const created = $input.first().json;
const lead_id = created.result;
if (typeof lead_id !== 'number' || !Number.isInteger(lead_id) || lead_id < 1) throw new Error('lead_id missing');
const features = {
  hashed_partner_id: inbound.hashed_partner_id,
  stage_rank: 1,
  days_in_stage: 0,
  product_family_code: inbound.product_family_code,
  order_count: 0,
};
if ('work_email' in features || 'contact_name' in features || 'company_name' in features) throw new Error('RED/AMBER key forbidden in lead score');
const stage = Number(features.stage_rank) || 0;
const recency = Math.max(0, 10 - (Number(features.days_in_stage) || 0)) / 10;
const orders = Math.min(Number(features.order_count) || 0, 3) / 3;
const score = Math.min(1, (stage / 3) * 0.5 + recency * 0.3 + orders * 0.2);
return [{ json: {
  lead_id,
  score: Math.round(score * 100) / 100,
  qualified: score >= 0.7,
  product_family_code: inbound.product_family_code,
} }];
